#ifndef _LOAD_KERNEL_H_
#define _LOAD_KERNEL_H_

#include "version_autogenerated.h"
#include "partition.h"
/* this struct is very similar to mtd_info */
struct part_info {
	struct partition_info *partition;
	/* Where in memory does this partition start? */
	u32 dest;
	void *priv;
};

struct kernel_loader {
	/* Return the header size  */
	int (* get_header_size)(void);

	/* Return true if there is a kernel contained at src */
	int (* check_magic)(u32 hdr_addr);

	/* Return the image size  */
	int (* get_image_size)(void);

	/* load the kernel from the src to dst, return the number
	 * of bytes copied if successful, zero if not */
	u32 (* load_kernel)(u32 *dest, u32 src, const char *kernel_filename);

	/* A brief description of the module (ie, "cramfs") */
	char *name;
};

#ifdef CRAMFS_LOAD
extern struct kernel_loader cramfs_load;
#endif
#ifdef UIMAGE_LOAD
extern struct kernel_loader uImage_load;
#endif
#ifdef JFFS2_LOAD
extern struct kernel_loader jffs2_load;
#endif
#ifdef ROMFS_LOAD
extern struct kernel_loader romfs_load;
#endif
#ifdef ELF_LOAD
extern struct kernel_loader elf_load;
#endif

/* load from flash */
int loader_file(struct part_info *part, const char *filename, unsigned int kernel_offset);
/* load from mem */
int load_from_memory(struct part_info *part, const char *filename, void *image_buff, unsigned int kernel_offset);

int get_image_len(struct partition_info *partition, unsigned int offset);
int set_image_buff(void *image_buff);
void* get_image_buff(void);
#endif /* _LOAD_KERNEL_H_ */
